INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (7, 17, 'theory', 'Quiz: Disjoint Sets and Backtracking');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 17, 0, 'How do you check in a disjoint-set structure that two elements are in the same group?', '["Compare their numbers: one group has consecutive numbers", "Find the roots of both elements and compare: the groups are the same if the roots are equal", "Run a breadth-first traversal of the whole graph from the first element", "Compare the sizes of the groups the elements belong to"]', 1, 'Each element climbs its parents up to the root; the root is the representative of the group. Two elements are in the same group if and only if their roots are the same.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 17, 1, 'What does path compression do?', '["Removes unneeded elements from the structure", "Stores the group size in every root", "Sorts the elements of a group in increasing order", "After a find, re-hangs all elements on the path straight onto the root"]', 3, 'The next search for those elements takes one step. The first search along a long chain stays expensive, but it also straightens the tree, so on average the operations are fast.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 17, 2, 'The edges of a graph are processed one by one through union. What does it mean when an edge''s ends already lie in the same group?', '["It closes a cycle: the vertices were already connected by another path", "It has no weight", "It connects two different components", "It is redundant: the graph is disconnected"]', 0, 'If the ends of an edge are already in one group, a path between them exists, and the new edge closes a cycle. This is exactly what Kruskal''s algorithm is built on: such edges are skipped.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 17, 3, 'What must a backtracking function always do after the recursive call?', '["Clear the whole list of answers", "Sort the partial answer", "Undo the choice, restoring the shared partial answer to its state before the step", "Return to the start of the program"]', 2, 'The template is choose, explore, undo. Without the undo, the shared list accumulates garbage from neighboring branches, and the following options will be computed wrongly.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 17, 4, 'Why, in the sum problem, do we sort the numbers and break the loop when a number is greater than the remainder?', '["So the answers are printed in descending order", "To use less memory for the list of answers", "Because recursion doesn''t work with unsorted numbers", "All following numbers are no smaller than the current one, so they won''t fit either: the branch can be safely cut"]', 3, 'After sorting, each following number is no smaller than the current one. If the current one is already greater than the remainder, the rest are too, so trying them is pointless. That is pruning.');
